/*getBuyerStatusCountMainSql_v2*/
SELECT
( SELECT COUNT(A.USER_ID) CNT FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C, CMSCATLG D WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BYIT_COMORG_CODE = B.BUYER AND B.CMS_CATLG_ID = D.CMS_CATLG_ID(+) AND D.STD_FLAG(+)='Y' AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N','Y','T') AND A.USER_ID = #{USER_ID} AND NVL(A.PRE_GR_FLAG,'N') = 'N' AND A.BUYER = #{BUYER} AND DECODE(A.BUYER, 'KRHONG0020', A.VERIF_NUM, 'X') IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM ICOMCMPY CM, ICOMCQDT GC WHERE CM.COM_CODE = A.BUYER AND CM.USING_CATAL_TYPE IN ('A','C') AND GC.BUYER = CM.BYCA_COMORG_CODE AND GC.BELOW_COMORG_CODE = A.BUYER AND GC.CONTRACT_NO = A.CONTRACT_NO AND GC.CONTRACT_SEQ = A.CONTRACT_SEQ AND GC.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND GC.STATUS = 'D' ) ) AS CART_CNT,
(SELECT COUNT(A.PR_SEQ) FROM ICOMPRDT A, ICOMPODT C WHERE A.BUYER = #{BUYER} AND A.CHANGE_DATE BETWEEN TO_CHAR(SYSDATE -150,'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND A.STATUS IN ('C','R') AND C.STATUS(+) <> 'D' AND A.RECV_FLAG NOT IN ('RR','GR') AND A.CHANGE_USER_ID = #{USER_ID} AND A.PR_NO = C.PR_NO(+) AND A.PR_SEQ = C.PR_SEQ(+) AND A.BUYER = C.BUYER(+) AND C.ITEM_QTY <> C.GR_QTY ) AS PR_CNT,
(SELECT COUNT(*) FROM ICOGPASSLN A, ICOGDOCU B WHERE A.COMPANY = #{BUYER} AND A.USER_ID = #{USER_ID} AND A.PASS_TP = '0' AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.USER_ID = B.USER_ID AND TO_CHAR(B.START_DATE, 'YYYYMMDD') BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND B.PASS_STATUS = 0 ) AS SEND_CNT, -- 결재상신
(SELECT COUNT(*) FROM ICOGDOCU A, ICOGPASSLN B WHERE A.COMPANY IN (SELECT BUYER FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{BUYER} FROM DUAL) AND A.PASS_STATUS = '0' AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND B.USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{USER_ID} FROM DUAL) AND B.PASS_TP IN ('1','2','3') AND B.PASS_KN IS NULL AND TO_CHAR(A.START_DATE,'YYYYMMDD') BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS RECV_CNT, (SELECT COUNT(*) FROM ICOGDOCU A, ICOGPASSLN B WHERE A.COMPANY = #{BUYER} AND A.PASS_STATUS = '0' AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND B.USER_ID = #{USER_ID} AND B.PASS_TP IN ('1','2','3') AND B.PASS_KN IS NULL AND A.EXTIF_TP = 'PR' AND TO_CHAR(A.START_DATE,'YYYYMMDD') BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS PR_RECV_CNT, (SELECT COUNT(*) FROM ICOGDOCU A, ICOGPASSLN B WHERE A.COMPANY = #{BUYER} AND A.PASS_STATUS = '0' AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND B.USER_ID = #{USER_ID} AND B.PASS_TP IN ('1','2','3') AND B.PASS_KN IS NULL AND A.EXTIF_TP = 'PX' AND TO_CHAR(A.START_DATE,'YYYYMMDD') BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS PX_RECV_CNT, ( SELECT COUNT(DISTINCT b.po_no||b.po_seq||d.inv_no) FROM ICOMPRDT A, ICOMPODT B, ICOMPOHD C, ICOMIVDT D, WMSIVDT E WHERE A.BUYER = #{BUYER} AND C.PO_CREATE_DATE BETWEEN to_char(add_months(sysdate,-1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND A.STATUS ^= 'D' AND A.BUYER = B.BUYER AND A.PR_NO = B.PR_NO AND A.PR_SEQ= B.PR_SEQ AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.BUYER = D.BUYER AND B.PO_NO = D.PO_NO AND B.PO_SEQ = D.PO_SEQ AND D.STATUS ^= 'D' AND C.STATUS ^= 'D' AND B.STATUS ^= 'D' AND D.BUYER = E.BUYER(+) AND D.INV_NO = E.S_INV_NO(+) AND D.INV_SEQ = E.S_INV_SEQ(+) AND E.STATUS(+) <> 'D' AND B.ITEM_QTY ^= B.GR_QTY AND B.IV_QTY > B.GR_QTY AND DECODE(B.PROCESS_TYPE,'0',D.INV_NO, E.INV_NO ) IS NOT NULL AND DECODE(B.PROCESS_TYPE,'0',NVL(D.GR_QTY,0), NVL(E.BUYER_GR_QTY,0)) <> DECODE(B.PROCESS_TYPE,'0',NVL(D.INV_QTY,0), NVL(E.INV_QTY,0)) AND (NVL(FLAGS.DEPT_FIX,'N') != 'Y' OR A.CHANGE_USER_DEPT = #{DEPT}) AND (NVL(FLAGS.PR_USER_FIX,'N') != 'Y' OR A.ADD_USER_ID = #{USER_ID}) AND (NVL(FLAGS.PO_USER_FIX,'N') != 'Y' OR A.PURCHASER_ID = #{USER_ID}) ) GR_CNT,
(SELECT COUNT(*) FROM KEPRQDT A WHERE A.BUYER IN (SELECT NVL(CODE2, #{BUYER}) FROM ICOMCOD3 WHERE BUYER = #{BUYER} AND TYPE = 'TGCM' AND CODE1 = #{USER_ID} AND FLAG = 'Y' UNION ALL SELECT #{BUYER} FROM DUAL) AND A.BTOA_USER_ID = DECODE((SELECT USER_GROUP FROM ICOMLUSR WHERE USER_ID = #{USER_ID} AND COM_CODE = #{BUYER}), 'A', A.BTOA_USER_ID, #{USER_ID}) AND A.STATUS IN ('C','R') AND A.BTOA_DATE BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND F_GET_RE_STTS(A.BUYER, A.QUOTATION_NO,A.QUOTATION_SEQ,A.REVISION,0) = 'RQ10' AND A.RECV_FLAG != 'TS' ) AS SOUR_CNT, (SELECT COUNT(*) FROM KEPRQDT A WHERE A.BUYER IN (SELECT NVL(CODE2, #{BUYER}) FROM ICOMCOD3 WHERE BUYER = #{BUYER} AND TYPE = 'TGCM' AND CODE1 = #{USER_ID} AND FLAG = 'Y' UNION ALL SELECT #{BUYER} FROM DUAL) AND A.BTOA_USER_ID = DECODE((SELECT USER_GROUP FROM ICOMLUSR WHERE USER_ID = #{USER_ID} AND COM_CODE = #{BUYER}), 'A', A.BTOA_USER_ID, #{USER_ID}) AND A.STATUS IN ('C','R') AND A.BTOA_DATE BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND F_GET_RE_STTS(A.BUYER, A.QUOTATION_NO,A.QUOTATION_SEQ,A.REVISION,0) = 'RQ05' AND A.RECV_FLAG != 'TS' ) AS SOUR_ING_CNT, (SELECT COUNT(*) FROM KEPRQDT A WHERE A.BUYER IN (SELECT NVL(CODE2, #{BUYER}) FROM ICOMCOD3 WHERE BUYER = #{BUYER} AND TYPE = 'TGCM' AND CODE1 = #{USER_ID} AND FLAG = 'Y' UNION ALL SELECT #{BUYER} FROM DUAL) AND A.BTOA_USER_ID = DECODE((SELECT USER_GROUP FROM ICOMLUSR WHERE USER_ID = #{USER_ID} AND COM_CODE = #{BUYER}), 'A', A.BTOA_USER_ID, #{USER_ID}) AND A.STATUS IN ('C','R') AND A.BTOA_DATE BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND F_GET_RE_STTS(A.BUYER, A.QUOTATION_NO,A.QUOTATION_SEQ,A.REVISION,0) = 'RQ04' AND A.RECV_FLAG != 'TS' ) AS SOUR_END_CNT, (SELECT COUNT(A.PR_SEQ) FROM ICOMPRDT A WHERE A.BUYER = #{BUYER} AND A.ADD_DATE BETWEEN to_char(add_months(sysdate,-1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND A.RECV_FLAG IN('GA','PR','PT') AND A.SAVE_FLAG IN( 'PR','PX') AND A.STATUS <> 'D' AND A.PURCHASER_DEPT = #{DEPT}
/* 2022.03.03 발주권 있는 사람만 건수 표기 */ AND (SELECT SUBSTR(ROLE,1,1) FROM ICOMLUSR WHERE USER_ID = #{USER_ID}) IN ('A', 'C', 'P', 'ALL') ) AS PO_CNT, (SELECT COUNT(PR.PR_SEQ) FROM ICOMPRDT PR WHERE PR.BUYER = #{BUYER} AND PR.CHANGE_USER_ID = #{USER_ID} AND F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 0) IN ('PX10') AND PR.ADD_DATE BETWEEN to_char(add_months(sysdate,-1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS PR_1_CNT, (SELECT COUNT(PR.PR_SEQ) FROM ICOMPRDT PR WHERE PR.BUYER = #{BUYER} AND PR.CHANGE_USER_ID = #{USER_ID} AND F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 0) IN ('PX20') AND PR.ADD_DATE BETWEEN to_char(add_months(sysdate,-1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS PR_2_CNT, (SELECT COUNT(PR.PR_SEQ) FROM ICOMPRDT PR WHERE PR.BUYER = #{BUYER} AND PR.CHANGE_USER_ID = #{USER_ID} AND F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 0) IN ('PX30','PX40','PX50','PX60') AND PR.ADD_DATE BETWEEN to_char(add_months(sysdate,-1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS PR_3_CNT, (SELECT COUNT(PR.PR_SEQ) FROM ICOMPRDT PR WHERE PR.BUYER = #{BUYER} AND PR.CHANGE_USER_ID = #{USER_ID} AND F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 0) IN ('PX70') AND PR.ADD_DATE BETWEEN to_char(add_months(sysdate,-1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') ) AS PR_4_CNT, ( SELECT COUNT(*) FROM KEPRQDT A, KEPQTDT B WHERE A.SO_CA_FLAG = 'SO' AND A.BUYER IN (SELECT NVL(CODE2, #{BUYER}) FROM ICOMCOD3 WHERE BUYER = #{BUYER} AND TYPE = 'TGCM' AND CODE1 = #{USER_ID} AND FLAG = 'Y' UNION ALL SELECT #{BUYER} FROM DUAL) AND A.ATOB_DATE BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND A.BUYER = B.BUYER AND A.QUOTATION_NO = B.QUOTATION_NO AND A.QUOTATION_SEQ = B.QUOTATION_SEQ AND A.REVISION = B.REVISION AND B.BID_SUCCESS_FLAG = 'Y' AND A.ATOB_UNIT_PRICE <> 0 AND A.CONFIRM_DATE IS NULL AND A.RECV_FLAG IN ('GA', 'GR') AND A.ATOB_SEND_FLAG = 'Y' AND A.STATUS IN ('C' ,'R') AND B.STATUS <> 'D' AND B.STATUS <> 'O' AND NVL(A.MSDS_STATUS, 'N') <> 'R' AND A.BTOA_USER_ID = DECODE((SELECT USER_GROUP FROM ICOMLUSR WHERE USER_ID = #{USER_ID} AND COM_CODE = #{BUYER}), 'A', A.BTOA_USER_ID, #{USER_ID})
AND TRIM(DECODE(A.MSDS_NO, 'MS99999999', '', A.MSDS_NO)) IS NOT NULL AND NVL(A.MSDS_STATUS, 'N') = 'A'
AND NVL(A.MSDS_STATUS, 'N') != 'A'
) AS AGMT_CNT
FROM DUAL LEFT JOIN ( SELECT NVL(B.COL01_DATA,'N') AS DEPT_FIX , NVL(B.COL02_DATA,'N') AS PR_USER_FIX , NVL(B.COL03_DATA,'N') AS PO_USER_FIX FROM BNTSLGDEF A, BNTSLGIMP B WHERE 1=1 AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND A.SLG_ID = B.SLG_ID AND A.SLG_ID = 'P07-0000008' AND NOT EXISTS (SELECT 'X' FROM ICOMLUSR WHERE USER_ID = #{USER_ID} AND USER_TYPE = 'A') AND ROWNUM = 1 ) FLAGS ON 1=1


		/*getManualInfo*/ 

                SELECT             
                      MANUAL_NAME,        
                      MANUAL_FLAG       
                 FROM ICOMCMPY     
                WHERE COM_CODE= #{BUYER}

/*getCustomerCenterList*/ SELECT ROWNUM NO, Y.CLAIM_TEXT, Y.VC_NO, Y.PO_NO, Y.CD_USER_NAME, Y.REQ_DATE, Y.RECV_FLAG_TEXT, Y.CD_DATE, Y.BUYER_ITEM_NO, Y.DS_USER_NAME, Y.DF_DATE, Y.RUB_TEXT, Y.REQ_USER_ID, Y.REQ_USER_NAME, Y.REQ_DEPT_CODE, Y.REQ_USER_DEPT, Y.CLAIM_TYPE, Y.RECV_FLAG, Y.BUYER, Y.BUYER_NAME, Y.RUB_TYPE, Y.CLAIM_TYPE_TEXT FROM ( SELECT ROWNUM NUM, X.CLAIM_TEXT, X.VC_NO, X.PO_NO, X.CD_USER_NAME, X.REQ_DATE, X.RECV_FLAG_TEXT, X.CD_DATE, X.BUYER_ITEM_NO, X.DS_USER_NAME, X.DF_DATE, X.RUB_TEXT, X.REQ_USER_ID, X.REQ_USER_NAME, X.REQ_DEPT_CODE, X.REQ_USER_DEPT, X.CLAIM_TYPE, X.RECV_FLAG, X.BUYER, X.BUYER_NAME, X.RUB_TYPE, X.CLAIM_TYPE_TEXT FROM ( SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC03' AND CODE = A.CLAIM_MASTER) AS CLAIM_TEXT, A.VC_NO, A.PO_NO, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CD_USER_ID) AS CD_USER_NAME, TO_CHAR(A.REQ_DATE,'YYYYMMDD') AS REQ_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC02' AND CODE = A.RECV_FLAG) AS RECV_FLAG_TEXT, TO_CHAR(A.CD_DATE,'YYYYMMDD') AS CD_DATE, A.BUYER_ITEM_NO, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.DS_USER_ID) AS DS_USER_NAME, TO_CHAR(A.DF_DATE,'YYYYMMDD') AS DF_DATE, DECODE(A.RUB_TYPE,'A','매우만족','B','만족','C','보통','D','불만','F','매우불만','미평가') AS RUB_TEXT, A.REQ_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.REQ_USER_ID) AS REQ_USER_NAME, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = A.REQ_USER_ID) AS REQ_DEPT_CODE, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = A.BUYER AND CODE = (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = A.REQ_USER_ID)) AS REQ_USER_DEPT, A.CLAIM_TYPE, A.RECV_FLAG, A.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BUYER_NAME, A.RUB_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = A.CLAIM_TYPE) AS CLAIM_TYPE_TEXT FROM KEPAVCDT A WHERE TO_CHAR(A.REQ_DATE,'YYYYMMDD') BETWEEN replace(#{fromDate},'/','') AND replace(#{toDate},'/','') AND A.SYS_TYPE = 'KA'
AND A.BUYER = #{buyer} AND A.REQ_USER_ID NOT IN (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = 'KRKORE0001') AND A.REQ_USER_ID = #{userid}
AND A.BUYER IN (SELECT CODE2 FROM ICOMCOD3 WHERE TYPE = 'VOC' AND BUYER = #{buyer} AND CODE1 = #{userid} AND FLAG = 'Y') AND A.REQ_USER_ID NOT IN (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = 'KRKORE0001')
AND A.BUYER = #{st_buyer_groups}
AND A.REQ_USER_ID = #{st_pur_user_id}
AND A.REQ_USER_ID IN (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = #{st_buyer_groups} AND DEPARTMENT = #{st_pur_dept_code} AND STATUS != 'D')
AND A.RECV_FLAG = #{st_recv_flag}
AND A.CLAIM_MASTER = #{st_claim_master}
ORDER BY A.REQ_DATE DESC, A.BUYER
) X ) Y

/*getCustomerCenterList_v2*/ SELECT ROWNUM NO, Y.CLAIM_TEXT, Y.VC_NO, Y.PO_NO, Y.CD_USER_NAME, Y.REQ_DATE, Y.RECV_FLAG_TEXT, Y.CD_DATE, Y.BUYER_ITEM_NO, Y.DS_USER_NAME, Y.DS_USER_ID, Y.DS_DEPT, Y.DF_DATE, Y.RUB_TEXT, Y.REQ_USER_ID, Y.REQ_USER_NAME, Y.REQ_DEPT_CODE, Y.REQ_USER_DEPT, Y.CLAIM_TYPE, Y.RECV_FLAG, Y.BUYER, Y.BUYER_NAME, Y.RUB_TYPE, Y.CLAIM_TYPE_TEXT, Y.REQ_REMARK, CASE WHEN LENGTH(Y.REQ_REMARK)<=30 THEN Y.REQ_REMARK ELSE SUBSTR(Y.REQ_REMARK,0,30)||'...' END AS REQ_REMARK_SUB, Y.DF_REMARK FROM ( SELECT ROWNUM NUM, X.CLAIM_TEXT, X.VC_NO, X.PO_NO, X.CD_USER_NAME, X.REQ_DATE, X.RECV_FLAG_TEXT, X.CD_DATE, X.BUYER_ITEM_NO, X.DS_USER_NAME, X.DS_USER_ID, X.DS_DEPT, X.DF_DATE, X.RUB_TEXT, X.REQ_USER_ID, X.REQ_USER_NAME, X.REQ_DEPT_CODE, X.REQ_USER_DEPT, X.CLAIM_TYPE, X.RECV_FLAG, X.BUYER, X.BUYER_NAME, X.RUB_TYPE, X.CLAIM_TYPE_TEXT, X.REQ_REMARK, X.DF_REMARK FROM ( SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC03' AND CODE = A.CLAIM_MASTER) AS CLAIM_TEXT, A.VC_NO, A.PO_NO, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CD_USER_ID) AS CD_USER_NAME, TO_CHAR(A.REQ_DATE,'YYYY.MM.DD') AS REQ_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC02' AND CODE = A.RECV_FLAG) AS RECV_FLAG_TEXT, TO_CHAR(A.CD_DATE,'YYYYMMDD') AS CD_DATE, A.BUYER_ITEM_NO, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.DS_USER_ID) AS DS_USER_NAME, A.DS_USER_ID, A.DS_DEPT, TO_CHAR(A.DF_DATE,'YYYY.MM.DD') AS DF_DATE, DECODE(A.RUB_TYPE,'A','매우만족','B','만족','C','보통','D','불만','F','매우불만','미평가') AS RUB_TEXT, A.REQ_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.REQ_USER_ID) AS REQ_USER_NAME, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = A.REQ_USER_ID) AS REQ_DEPT_CODE, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = A.BUYER AND CODE = (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = A.REQ_USER_ID)) AS REQ_USER_DEPT, A.CLAIM_TYPE, A.RECV_FLAG, A.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BUYER_NAME, A.RUB_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = A.CLAIM_TYPE) AS CLAIM_TYPE_TEXT, A.REQ_REMARK, A.DF_REMARK FROM KEPAVCDT A WHERE A.SYS_TYPE = 'KA'
AND TO_CHAR(A.REQ_DATE,'YYYYMMDD') BETWEEN #{fromDate} AND #{toDate}
AND A.RECV_FLAG != 'GD'
AND A.BUYER = #{st_com_code} AND A.REQ_USER_ID NOT IN (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = 'KRKORE0001') AND A.REQ_USER_ID = #{st_user_id}
AND A.BUYER IN (SELECT CODE2 FROM ICOMCOD3 WHERE TYPE = 'VOC' AND BUYER = #{st_com_code} AND CODE1 = #{st_user_id} AND FLAG = 'Y') AND A.REQ_USER_ID NOT IN (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = 'KRKORE0001')
AND A.BUYER = #{st_buyer_groups}
AND A.REQ_USER_ID = #{st_pur_user_id}
AND A.REQ_USER_ID IN (SELECT USER_ID FROM ICOMLUSR WHERE COM_CODE = #{st_buyer_groups} AND DEPARTMENT = #{st_pur_dept_code} AND STATUS != 'D')
AND A.RECV_FLAG = #{st_recv_flag}
AND A.CLAIM_MASTER = #{st_claim_master}
ORDER BY A.REQ_DATE DESC, A.BUYER ) X ) Y
WHERE ROWNUM <= 4

/*getSrsysType*/
SELECT
CODE,TEXT1
FROM ICOMCOD1 WHERE TYPE = #{TYPE}

mapper.update:

 		/*setCustomerRubUpdate*/ 

 		UPDATE KEPAVCDT SET           
		   RUB_TYPE=#{RUB_TYPE}  
	WHERE BUYER=#{BUYER}             
	  AND VC_NO=#{VC_NO}                
	  AND REQ_USER_ID=#{REQ_USER_ID}

mapper.select:

/* getChkVocAtckFor1Min */
SELECT	TO_CHAR(SYSDATE, 'YYYYMMDDHH24MI') - TO_CHAR(MAX(REQ_DATE), 'YYYYMMDDHH24MI')
FROM	KEPAVCDT
WHERE	REQ_USER_ID = #{userid}


/* getChkVocAtckFor30Mins */
SELECT	COUNT(*)
FROM	KEPAVCDT
WHERE	1=1
AND		REQ_USER_ID = #{userid}
AND		TO_CHAR(REQ_DATE, 'YYYYMMDDHH24MI') BETWEEN TO_CHAR(SYSDATE - (INTERVAL '30' MINUTE), 'YYYYMMDDHH24MI') AND TO_CHAR(SYSDATE, 'YYYYMMDDHH24MI')

mapper.update:

 		/*setCustomerVocCancel_v2*/ 
 		UPDATE KEPAVCDT					
			   SET RECV_FLAG      = 'GD' 	
			     , CANCEL_USER_ID = #{st_user_id} 
			     , CANCEL_DATE    = SYSDATE	
			     , CANCEL_NOTE  = #{CANCEL_NOTE}
	  WHERE VC_NO=#{st_vc_no}                
	  AND REQ_USER_ID=#{st_user_id}
